:root {
  --color-primary: #1a5490;
  --color-primary-dark: #0d3a66;
  --color-primary-light: #2a7ec9;
  --color-accent: #ff6b35;
  --color-accent-dark: #cc5529;
  --color-accent-on-dark: #ffb380;
  --color-success: #28a745;
  --color-neutral-light: #f8f9fa;
  --color-neutral-medium: #e9ecef;
  --color-neutral-dark: #495057;
  --color-text: #212529;
  --color-text-light: #6c757d;
  --color-border: #dee2e6;
  --font-serif: Georgia, "Times New Roman", serif;
  --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --font-mono: "Courier New", monospace;
  --spacing-xs: 0.5rem;
  --spacing-sm: 1rem;
  --spacing-md: 1.5rem;
  --spacing-lg: 2rem;
  --spacing-xl: 3rem;
  --spacing-2xl: 4rem;
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --shadow-sm: 0 1px 3px rgba(0, 0, 0, 0.12);
  --shadow-md: 0 4px 12px rgba(0, 0, 0, 0.15);
  --shadow-lg: 0 8px 24px rgba(0, 0, 0, 0.18);
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  font-size: 16px;
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-sans);
  font-size: 1rem;
  line-height: 1.6;
  color: var(--color-text);
  background-color: #ffffff;
}

h1 {
  font-size: clamp(2rem, 5vw, 3.5rem);
  font-weight: 700;
  line-height: 1.2;
  margin-bottom: var(--spacing-md);
  color: var(--color-primary-dark);
}

h2 {
  font-size: clamp(1.75rem, 4vw, 2.5rem);
  font-weight: 700;
  line-height: 1.2;
  margin-bottom: var(--spacing-md);
  color: var(--color-primary-dark);
}

h3 {
  font-size: 1.5rem;
  font-weight: 700;
  margin-bottom: var(--spacing-sm);
  color: var(--color-primary-dark);
}

h4 {
  font-size: 1.25rem;
  font-weight: 600;
  margin-bottom: var(--spacing-sm);
  color: var(--color-text);
}

p {
  margin-bottom: var(--spacing-sm);
}

a {
  color: var(--color-primary);
  text-decoration: none;
  transition: color 0.2s ease;
}

a:hover {
  color: var(--color-primary-light);
  text-decoration: underline;
}

a:focus-visible {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
  border-radius: 2px;
}

.container {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 var(--spacing-md);
}

.site-header {
  background-color: var(--color-primary-dark);
  color: #ffffff;
  padding: var(--spacing-md) 0;
  position: sticky;
  top: 0;
  z-index: 100;
  box-shadow: var(--shadow-sm);
}

.site-header .container {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: var(--spacing-lg);
}

.logo {
  font-family: var(--font-mono);
  font-size: clamp(1.2rem, 3vw, 1.5rem);
  font-weight: 700;
  letter-spacing: 0.05em;
  color: #ffffff;
  text-decoration: none;
  white-space: nowrap;
  transition: color 0.2s ease;
}

.logo:hover {
  color: var(--color-accent-on-dark);
}

.logo:focus-visible {
  outline: 3px solid var(--color-accent);
  outline-offset: 4px;
  border-radius: 2px;
}

.site-header nav {
  display: flex;
  gap: var(--spacing-lg);
  align-items: center;
  flex-wrap: wrap;
}

.site-header nav a {
  color: #ffffff;
  font-size: 1rem;
  font-weight: 500;
  transition: color 0.2s ease;
  padding-bottom: 0.25rem;
  border-bottom: 2px solid transparent;
}

.site-header nav a:hover {
  color: var(--color-accent-on-dark);
  text-decoration: none;
  border-bottom-color: var(--color-accent-on-dark);
}

.site-header nav a:focus-visible {
  outline: 3px solid var(--color-accent);
  outline-offset: 4px;
  border-radius: 2px;
}

.site-footer {
  background-color: var(--color-primary-dark);
  color: #ffffff;
  padding: var(--spacing-2xl) 0;
  margin-top: var(--spacing-2xl);
}

.site-footer .container {
  text-align: center;
}

.site-footer p {
  margin-bottom: var(--spacing-sm);
  font-size: 0.95rem;
}

.site-footer a {
  color: var(--color-accent-on-dark);
}

.site-footer a:hover {
  color: #ffffff;
  text-decoration: underline;
}

button,
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 44px;
  padding: var(--spacing-sm) var(--spacing-md);
  font-size: 1rem;
  font-weight: 600;
  font-family: var(--font-sans);
  border: 2px solid transparent;
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: all 0.2s ease;
  text-decoration: none;
  gap: var(--spacing-xs);
}

button:focus-visible,
.btn:focus-visible {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}

.btn-primary {
  background-color: var(--color-primary-dark);
  color: #ffffff;
  border-color: var(--color-primary-dark);
}

.btn-primary:hover {
  background-color: var(--color-primary);
  border-color: var(--color-primary);
}

.btn-primary:active {
  background-color: var(--color-primary-dark);
  transform: scale(0.98);
}

.btn-secondary {
  background-color: var(--color-accent-dark);
  color: #ffffff;
  border-color: var(--color-accent-dark);
}

.btn-secondary:hover {
  background-color: var(--color-accent);
  border-color: var(--color-accent);
}

.btn-secondary:active {
  background-color: var(--color-accent-dark);
  transform: scale(0.98);
}

.btn-outline {
  background-color: transparent;
  color: var(--color-primary-dark);
  border-color: var(--color-primary-dark);
}

.btn-outline:hover {
  background-color: var(--color-primary-dark);
  color: #ffffff;
}

.btn-small {
  padding: var(--spacing-xs) var(--spacing-sm);
  font-size: 0.9rem;
  min-height: 40px;
}

input[type="text"],
input[type="email"],
input[type="password"],
input[type="date"],
input[type="number"],
textarea,
select {
  width: 100%;
  padding: var(--spacing-sm);
  font-size: 1rem;
  font-family: var(--font-sans);
  border: 2px solid var(--color-border);
  border-radius: var(--radius-md);
  background-color: #ffffff;
  color: var(--color-text);
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
  min-height: 44px;
}

input[type="text"]:focus,
input[type="email"]:focus,
input[type="password"]:focus,
input[type="date"]:focus,
input[type="number"]:focus,
textarea:focus,
select:focus {
  outline: none;
  border-color: var(--color-primary-dark);
  box-shadow: 0 0 0 3px rgba(26, 84, 144, 0.1);
}

label {
  display: block;
  margin-bottom: var(--spacing-xs);
  font-weight: 600;
  color: var(--color-text);
}

.form-group {
  margin-bottom: var(--spacing-md);
}

.card {
  background-color: #ffffff;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--spacing-lg);
  transition: box-shadow 0.2s ease, transform 0.2s ease;
}

.card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.speaker-card {
  text-align: center;
}

.speaker-card img {
  width: 100%;
  height: 250px;
  object-fit: cover;
  border-radius: var(--radius-md);
  margin-bottom: var(--spacing-md);
}

.speaker-card h3 {
  margin-bottom: var(--spacing-xs);
}

.speaker-card .role {
  font-size: 0.9rem;
  color: var(--color-primary);
  font-weight: 600;
  margin-bottom: var(--spacing-xs);
}

.speaker-card .company {
  font-size: 0.85rem;
  color: var(--color-text-light);
  margin-bottom: var(--spacing-sm);
}

.speaker-card .bio {
  font-size: 0.9rem;
  line-height: 1.5;
  color: var(--color-text-light);
}

.grid {
  display: grid;
  gap: var(--spacing-lg);
}

.grid-2 {
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
}

.grid-3 {
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
}

.grid-4 {
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
}

table {
  width: 100%;
  border-collapse: collapse;
  margin-bottom: var(--spacing-lg);
  font-size: 0.95rem;
}

table thead {
  background-color: var(--color-primary-dark);
  color: #ffffff;
}

table th,
table td {
  padding: var(--spacing-sm);
  text-align: left;
  border-bottom: 1px solid var(--color-border);
}

table tbody tr:hover {
  background-color: var(--color-neutral-light);
}

table tbody tr:nth-child(even) {
  background-color: #ffffff;
}

.badge {
  display: inline-block;
  padding: 0.25rem 0.75rem;
  font-size: 0.8rem;
  font-weight: 600;
  border-radius: 20px;
  background-color: var(--color-neutral-medium);
  color: var(--color-text);
}

.badge-primary {
  background-color: var(--color-primary);
  color: #ffffff;
}

.badge-accent {
  background-color: var(--color-accent);
  color: #ffffff;
}

.badge-success {
  background-color: var(--color-success);
  color: #ffffff;
}

.section {
  padding: var(--spacing-2xl) 0;
}

.section-title {
  text-align: center;
  margin-bottom: var(--spacing-2xl);
}

.hero {
  background: linear-gradient(135deg, var(--color-primary-dark) 0%, var(--color-primary) 100%);
  color: #ffffff;
  padding: var(--spacing-2xl) 0;
  text-align: center;
}

.hero h1 {
  color: #ffffff;
  margin-bottom: var(--spacing-md);
}

.hero p {
  font-size: 1.25rem;
  margin-bottom: var(--spacing-lg);
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

.hero-cta {
  display: flex;
  gap: var(--spacing-md);
  justify-content: center;
  flex-wrap: wrap;
}

.highlight-box {
  background-color: var(--color-neutral-light);
  padding: var(--spacing-lg);
  border-radius: var(--radius-lg);
  border-left: 4px solid var(--color-accent);
}

.highlight-box strong {
  color: var(--color-primary-dark);
}

@media (max-width: 600px) {
  html {
    font-size: 14px;
  }

  .site-header .container {
    flex-direction: column;
    gap: var(--spacing-md);
  }

  .site-header nav {
    gap: var(--spacing-md);
    justify-content: center;
    width: 100%;
  }

  .site-header nav a {
    font-size: 0.9rem;
  }

  h1 {
    font-size: 1.75rem;
  }

  h2 {
    font-size: 1.5rem;
  }

  h3 {
    font-size: 1.25rem;
  }

  .container {
    padding: 0 var(--spacing-sm);
  }

  .grid-2,
  .grid-3,
  .grid-4 {
    grid-template-columns: 1fr;
  }

  table {
    font-size: 0.85rem;
  }

  table th,
  table td {
    padding: 0.5rem 0.25rem;
  }

  .card {
    padding: var(--spacing-md);
  }

  .hero {
    padding: var(--spacing-xl) 0;
  }

  .hero p {
    font-size: 1rem;
  }

  .hero-cta {
    flex-direction: column;
  }

  .hero-cta .btn {
    width: 100%;
  }

  .section {
    padding: var(--spacing-xl) 0;
  }

  .section-title {
    margin-bottom: var(--spacing-xl);
  }
}

@media (min-width: 601px) {
  .site-header nav {
    gap: var(--spacing-xl);
  }

  .grid {
    gap: var(--spacing-xl);
  }

  table {
    font-size: 1rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  * {
    animation: none !important;
    transition: none !important;
  }
}

pages.css:
.speakers-intro {
  padding: var(--spacing-xl) 0;
  text-align: center;
  max-width: 700px;
  margin: 0 auto;
}

.speakers-intro p {
  font-size: 1.1rem;
  color: var(--color-text-light);
  line-height: 1.8;
}

.speakers-grid-section {
  padding: var(--spacing-2xl) 0;
}

.speakers-filter {
  margin-bottom: var(--spacing-2xl);
  max-width: 400px;
  margin-left: auto;
  margin-right: auto;
}

.speakers-search-input {
  width: 100%;
  padding: var(--spacing-sm);
  font-size: 1rem;
  border: 2px solid var(--color-border);
  border-radius: var(--radius-md);
  min-height: 44px;
}

.speakers-search-input:focus {
  border-color: var(--color-primary-dark);
  box-shadow: 0 0 0 3px rgba(26, 84, 144, 0.1);
  outline: none;
}

.speakers-expanded-bio {
  margin-top: var(--spacing-md);
  padding-top: var(--spacing-md);
  border-top: 1px solid var(--color-border);
  font-size: 0.95rem;
  line-height: 1.6;
  color: var(--color-text-light);
}

.speakers-expand {
  margin-top: var(--spacing-md);
  width: 100%;
}

@media (max-width: 600px) {
  .speakers-intro {
    padding: var(--spacing-xl) 0;
  }

  .speakers-intro p {
    font-size: 1rem;
  }

  .speakers-grid-section {
    padding: var(--spacing-xl) 0;
  }

  .speakers-filter {
    margin-bottom: var(--spacing-xl);
  }
}

@media (min-width: 601px) {
  .speakers-intro p {
    margin-bottom: 0;
  }
}

.schedule-hero {
  background: linear-gradient(135deg, var(--color-primary-dark) 0%, var(--color-primary) 100%);
  color: #ffffff;
  padding: var(--spacing-2xl) 0;
  text-align: center;
}

.schedule-hero h1 {
  color: #ffffff;
  margin-bottom: var(--spacing-sm);
}

.schedule-hero p {
  font-size: 1.1rem;
  color: var(--color-accent-on-dark);
}

.schedule-filters {
  padding: var(--spacing-lg) 0;
  background-color: var(--color-neutral-light);
  border-bottom: 1px solid var(--color-border);
}

.schedule-day-selector {
  display: flex;
  gap: var(--spacing-md);
  justify-content: center;
  flex-wrap: wrap;
}

.schedule-day-btn {
  padding: var(--spacing-sm) var(--spacing-md);
  min-height: 44px;
  font-size: 0.95rem;
  font-weight: 600;
  border: 2px solid var(--color-primary-dark);
  background-color: #ffffff;
  color: var(--color-primary-dark);
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: all 0.2s ease;
}

.schedule-day-btn:hover {
  background-color: var(--color-primary-dark);
  color: #ffffff;
}

.schedule-day-btn--active {
  background-color: var(--color-primary-dark);
  color: #ffffff;
  border-color: var(--color-primary-dark);
}

.schedule-day-btn:focus-visible {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}

.schedule-content {
  padding: var(--spacing-2xl) 0;
}

.schedule-table-wrapper {
  overflow-x: auto;
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-md);
}

.schedule-table {
  border-collapse: collapse;
  background-color: #ffffff;
}

.schedule-table thead {
  background-color: var(--color-primary-dark);
  color: #ffffff;
  font-weight: 600;
}

.schedule-table th {
  padding: var(--spacing-md);
  text-align: left;
  border-bottom: 2px solid var(--color-primary-dark);
}

.schedule-table td {
  padding: var(--spacing-md);
  border-bottom: 1px solid var(--color-border);
}

.schedule-table tbody tr {
  transition: background-color 0.2s ease;
}

.schedule-table tbody tr:hover {
  background-color: var(--color-neutral-light);
}

.schedule-table tbody tr:nth-child(even) {
  background-color: #ffffff;
}

.schedule-row strong {
  color: var(--color-primary-dark);
  font-weight: 700;
}

.schedule-legend {
  padding: var(--spacing-2xl) 0;
  background-color: var(--color-neutral-light);
}

.schedule-legend h2 {
  text-align: center;
  margin-bottom: var(--spacing-2xl);
}

.schedule-legend-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: var(--spacing-lg);
}

.schedule-legend-item {
  padding: var(--spacing-lg);
  background-color: #ffffff;
  border-radius: var(--radius-md);
  border: 1px solid var(--color-border);
}

.schedule-legend-item .badge {
  display: block;
  margin-bottom: var(--spacing-sm);
}

.schedule-legend-item p {
  font-size: 0.9rem;
  color: var(--color-text-light);
  line-height: 1.5;
  margin: 0;
}

.schedule-cta {
  padding: var(--spacing-2xl) 0;
  text-align: center;
  background-color: var(--color-primary-dark);
  color: #ffffff;
}

.schedule-cta h2 {
  color: #ffffff;
  margin-bottom: var(--spacing-md);
}

.schedule-cta p {
  font-size: 1.1rem;
  margin-bottom: var(--spacing-lg);
  color: var(--color-accent-on-dark);
}

.schedule-cta .btn {
  font-size: 1.05rem;
  padding: var(--spacing-md) var(--spacing-lg);
}

@media (max-width: 600px) {
  .schedule-hero {
    padding: var(--spacing-xl) 0;
  }

  .schedule-hero h1 {
    font-size: 1.75rem;
  }

  .schedule-hero p {
    font-size: 1rem;
  }

  .schedule-filters {
    padding: var(--spacing-md) 0;
  }

  .schedule-day-selector {
    gap: var(--spacing-sm);
  }

  .schedule-day-btn {
    padding: var(--spacing-xs) var(--spacing-sm);
    font-size: 0.85rem;
    min-height: 40px;
  }

  .schedule-content {
    padding: var(--spacing-xl) 0;
  }

  .schedule-table-wrapper {
    overflow-x: auto;
    -webkit-overflow-scrolling: touch;
  }

  .schedule-table th,
  .schedule-table td {
    padding: var(--spacing-sm) 0.5rem;
    font-size: 0.85rem;
  }

  .schedule-table th {
    font-size: 0.8rem;
  }

  .schedule-legend {
    padding: var(--spacing-xl) 0;
  }

  .schedule-legend-grid {
    grid-template-columns: 1fr;
    gap: var(--spacing-md);
  }

  .schedule-cta {
    padding: var(--spacing-xl) 0;
  }

  .schedule-cta h2 {
    font-size: 1.5rem;
  }

  .schedule-cta p {
    font-size: 1rem;
  }
}

@media (min-width: 601px) {
  .schedule-content {
    padding: var(--spacing-2xl) var(--spacing-xl);
  }

  .schedule-table-wrapper {
    margin-bottom: var(--spacing-lg);
  }

  .schedule-legend-grid {
    grid-template-columns: repeat(4, 1fr);
  }
}

.tickets-grid {
  margin-bottom: var(--spacing-xl);
}

.ticket-card {
  display: flex;
  flex-direction: column;
  background-color: #ffffff;
  border: 2px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--spacing-lg);
  transition: all 0.3s ease;
  position: relative;
}

.ticket-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.ticket-card-featured {
  border-color: var(--color-accent-dark);
  border-width: 3px;
  background: linear-gradient(135deg, rgba(255, 107, 53, 0.02) 0%, rgba(255, 107, 53, 0.05) 100%);
}

.ticket-badge {
  position: absolute;
  top: -12px;
  right: 20px;
  background-color: var(--color-accent-dark);
  color: #ffffff;
  padding: 0.5rem 1rem;
  border-radius: 20px;
  font-size: 0.85rem;
  font-weight: 700;
  box-shadow: var(--shadow-md);
}

.ticket-header {
  margin-bottom: var(--spacing-md);
}

.ticket-header h3 {
  margin-bottom: 0.25rem;
  color: var(--color-primary-dark);
}

.ticket-availability {
  font-size: 0.85rem;
  color: var(--color-text-light);
  margin: 0;
}

.ticket-price {
  margin-bottom: var(--spacing-md);
  padding-bottom: var(--spacing-md);
  border-bottom: 2px solid var(--color-border);
}

.price-amount {
  display: block;
  font-size: 2.5rem;
  font-weight: 700;
  color: var(--color-accent-dark);
}

.price-period {
  display: block;
  font-size: 0.9rem;
  color: var(--color-text-light);
  margin-top: 0.25rem;
}

.ticket-description {
  font-size: 0.95rem;
  color: var(--color-text-light);
  margin-bottom: var(--spacing-md);
  line-height: 1.5;
}

.ticket-features {
  list-style: none;
  margin-bottom: var(--spacing-lg);
  flex-grow: 1;
}

.ticket-features li {
  padding-left: 1.75rem;
  position: relative;
  margin-bottom: 0.75rem;
  font-size: 0.95rem;
  color: var(--color-text);
}

.ticket-features li::before {
  content: "✓";
  position: absolute;
  left: 0;
  font-weight: 700;
  color: var(--color-success);
}

.tickets-btn {
  width: 100%;
  margin-top: auto;
}

.tickets-info-section {
  background-color: var(--color-neutral-light);
}

.tickets-info-list {
  list-style: none;
}

.tickets-info-list li {
  padding-left: 1.75rem;
  position: relative;
  margin-bottom: 1rem;
  font-size: 0.95rem;
  line-height: 1.6;
}

.tickets-info-list li::before {
  content: "•";
  position: absolute;
  left: 0;
  color: var(--color-accent-dark);
  font-weight: 700;
}

.tickets-faq-section {
  background-color: #ffffff;
}

.tickets-faq-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(350px, 1fr));
  gap: var(--spacing-lg);
}

.faq-item {
  background-color: var(--color-neutral-light);
  border-radius: var(--radius-md);
  overflow: hidden;
  border: 1px solid var(--color-border);
  transition: box-shadow 0.2s ease;
}

.faq-item:hover {
  box-shadow: var(--shadow-sm);
}

.faq-item summary {
  padding: var(--spacing-md);
  cursor: pointer;
  user-select: none;
  transition: background-color 0.2s ease;
}

.faq-item summary:hover {
  background-color: var(--color-neutral-medium);
}

.faq-item summary:focus-visible {
  outline: 3px solid var(--color-accent);
  outline-offset: -2px;
}

.faq-item summary h4 {
  margin: 0;
  color: var(--color-primary-dark);
}

.faq-item p {
  padding: 0 var(--spacing-md) var(--spacing-md) var(--spacing-md);
  color: var(--color-text);
  line-height: 1.6;
}

.faq-item p:last-child {
  margin-bottom: 0;
}

.tickets-support-section {
  background-color: #ffffff;
}

.tickets-support-grid {
  margin-top: var(--spacing-xl);
}

.support-card {
  background-color: var(--color-neutral-light);
  padding: var(--spacing-lg);
  border-radius: var(--radius-lg);
  border-left: 4px solid var(--color-primary-dark);
}

.support-card h4 {
  color: var(--color-primary-dark);
  margin-bottom: var(--spacing-sm);
}

.support-card p {
  margin-bottom: 0.75rem;
  font-size: 0.95rem;
}

.support-card a {
  color: var(--color-accent-dark);
  font-weight: 600;
}

.support-card a:hover {
  color: var(--color-accent);
}

@media (max-width: 600px) {
  .tickets-grid {
    margin-bottom: var(--spacing-lg);
  }

  .ticket-card {
    padding: var(--spacing-md);
  }

  .ticket-badge {
    right: 10px;
    padding: 0.4rem 0.75rem;
    font-size: 0.75rem;
  }

  .price-amount {
    font-size: 2rem;
  }

  .ticket-features li {
    font-size: 0.9rem;
    margin-bottom: 0.5rem;
  }

  .tickets-faq-grid {
    grid-template-columns: 1fr;
    gap: var(--spacing-md);
  }

  .tickets-support-grid {
    grid-template-columns: 1fr;
  }
}

@media (min-width: 601px) {
  .tickets-faq-grid {
    gap: var(--spacing-xl);
  }
}

final.css:
:root {
  --color-accent-dark-bg: #d33800;
  --color-primary: #1a5490;
  --color-primary-dark: #0d3a66;
  --color-primary-light: #2a7ec9;
  --color-accent: #d33800;
  --color-accent-dark: #bf5026;
  --color-accent-on-dark: #ffb380;
  --color-success: #28a745;
  --color-neutral-light: #f8f9fa;
  --color-neutral-medium: #e9ecef;
  --color-neutral-dark: #495057;
  --color-text: #212529;
  --color-text-light: #6c757d;
  --color-border: #dee2e6;
  --font-serif: Georgia, "Times New Roman", serif;
  --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --font-mono: "Courier New", monospace;
  --spacing-xs: 0.5rem;
  --spacing-sm: 1rem;
  --spacing-md: 1.5rem;
  --spacing-lg: 2rem;
  --spacing-xl: 3rem;
  --spacing-2xl: 4rem;
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --shadow-sm: 0 1px 3px rgba(0, 0, 0, 0.12);
  --shadow-md: 0 4px 12px rgba(0, 0, 0, 0.15);
  --shadow-lg: 0 8px 24px rgba(0, 0, 0, 0.18);
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  font-size: 16px;
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-sans);
  font-size: 1rem;
  line-height: 1.6;
  color: var(--color-text);
  background-color: #ffffff;
}

h1 {
  font-size: clamp(2rem, 5vw, 3.5rem);
  font-weight: 700;
  line-height: 1.2;
  margin-bottom: var(--spacing-md);
  color: var(--color-primary-dark);
}

h2 {
  font-size: clamp(1.75rem, 4vw, 2.5rem);
  font-weight: 700;
  line-height: 1.2;
  margin-bottom: var(--spacing-md);
  color: var(--color-primary-dark);
}

h3 {
  font-size: 1.5rem;
  font-weight: 700;
  margin-bottom: var(--spacing-sm);
  color: var(--color-primary-dark);
}

h4 {
  font-size: 1.25rem;
  font-weight: 600;
  margin-bottom: var(--spacing-sm);
  color: var(--color-text);
}

p {
  margin-bottom: var(--spacing-sm);
}

a {
  color: var(--color-primary);
  text-decoration: underline;
  transition: color 0.2s ease;
}

a:hover {
  color: var(--color-primary-light);
  text-decoration: underline;
}

a:focus-visible {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
  border-radius: 2px;
}

.container {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 var(--spacing-md);
}

.site-header {
  background-color: var(--color-primary-dark);
  color: #ffffff;
  padding: var(--spacing-md) 0;
  position: sticky;
  top: 0;
  z-index: 100;
  box-shadow: var(--shadow-sm);
}

.site-header .container {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: var(--spacing-lg);
}

.logo {
  font-family: var(--font-mono);
  font-size: clamp(1.2rem, 3vw, 1.5rem);
  font-weight: 700;
  letter-spacing: 0.05em;
  color: #ffffff;
  text-decoration: none;
  white-space: nowrap;
  transition: color 0.2s ease;
}

.logo:hover {
  color: var(--color-accent-on-dark);
}

.logo:focus-visible {
  outline: 3px solid var(--color-accent);
  outline-offset: 4px;
  border-radius: 2px;
}

.site-header nav {
  display: flex;
  gap: var(--spacing-lg);
  align-items: center;
  flex-wrap: wrap;
}

.site-header nav a {
  color: #ffffff;
  font-size: 1rem;
  font-weight: 500;
  transition: color 0.2s ease;
  padding-bottom: 0.25rem;
  border-bottom: 2px solid transparent;
}

.site-header nav a:hover {
  color: var(--color-accent-on-dark);
  text-decoration: none;
  border-bottom-color: var(--color-accent-on-dark);
}

.site-header nav a:focus-visible {
  outline: 3px solid var(--color-accent);
  outline-offset: 4px;
  border-radius: 2px;
}

.site-footer {
  background-color: var(--color-primary-dark);
  color: #ffffff;
  padding: var(--spacing-2xl) 0;
  margin-top: var(--spacing-2xl);
}

.site-footer .container {
  text-align: center;
}

.site-footer p {
  margin-bottom: var(--spacing-sm);
  font-size: 0.95rem;
}

.site-footer a {
  color: var(--color-accent-on-dark);
}

.site-footer a:hover {
  color: #ffffff;
  text-decoration: underline;
}

button,
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 44px;
  padding: var(--spacing-sm) var(--spacing-md);
  font-size: 1rem;
  font-weight: 600;
  font-family: var(--font-sans);
  border: 2px solid transparent;
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: all 0.2s ease;
  text-decoration: none;
  gap: var(--spacing-xs);
}

button:focus-visible,
.btn:focus-visible {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}

.btn-primary {
  background-color: var(--color-primary-dark);
  color: #ffffff;
  border-color: var(--color-primary-dark);
}

.btn-primary:hover {
  background-color: var(--color-primary);
  border-color: var(--color-primary);
}

.btn-primary:active {
  background-color: var(--color-primary-dark);
  transform: scale(0.98);
}

.btn-secondary {
  background-color: var(--color-accent-dark);
  color: #ffffff;
  border-color: var(--color-accent-dark);
}

.btn-secondary:hover {
  background-color: var(--color-accent);
  border-color: var(--color-accent);
}

.btn-secondary:active {
  background-color: var(--color-accent-dark);
  transform: scale(0.98);
}

.btn-outline {
  background-color: transparent;
  color: var(--color-primary-dark);
  border-color: var(--color-primary-dark);
}

.btn-outline:hover {
  background-color: var(--color-primary-dark);
  color: #ffffff;
}

.btn-small {
  padding: var(--spacing-xs) var(--spacing-sm);
  font-size: 0.9rem;
  min-height: 40px;
}

input[type="text"],
input[type="email"],
input[type="password"],
input[type="date"],
input[type="number"],
textarea,
select {
  width: 100%;
  padding: var(--spacing-sm);
  font-size: 1rem;
  font-family: var(--font-sans);
  border: 2px solid var(--color-border);
  border-radius: var(--radius-md);
  background-color: #ffffff;
  color: var(--color-text);
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
  min-height: 44px;
}

input[type="text"]:focus,
input[type="email"]:focus,
input[type="password"]:focus,
input[type="date"]:focus,
input[type="number"]:focus,
textarea:focus,
select:focus {
  outline: none;
  border-color: var(--color-primary-dark);
  box-shadow: 0 0 0 3px rgba(26, 84, 144, 0.1);
}

label {
  display: block;
  margin-bottom: var(--spacing-xs);
  font-weight: 600;
  color: var(--color-text);
}

.form-group {
  margin-bottom: var(--spacing-md);
}

.card {
  background-color: #ffffff;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--spacing-lg);
  transition: box-shadow 0.2s ease, transform 0.2s ease;
}

.card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.speaker-card {
  text-align: center;
}

.speaker-card img {
  width: 100%;
  height: 250px;
  object-fit: cover;
  border-radius: var(--radius-md);
  margin-bottom: var(--spacing-md);
}

.speaker-card h3 {
  margin-bottom: var(--spacing-xs);
}

.speaker-card .role {
  font-size: 0.9rem;
  color: var(--color-primary);
  font-weight: 600;
  margin-bottom: var(--spacing-xs);
}

.speaker-card .company {
  font-size: 0.85rem;
  color: var(--color-text-light);
  margin-bottom: var(--spacing-sm);
}

.speaker-card .bio {
  font-size: 0.9rem;
  line-height: 1.5;
  color: var(--color-text-light);
}

.grid {
  display: grid;
  gap: var(--spacing-lg);
}

.grid-2 {
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
}

.grid-3 {
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
}

.grid-4 {
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
}

table {
  width: 100%;
  border-collapse: collapse;
  margin-bottom: var(--spacing-lg);
  font-size: 0.95rem;
}

table thead {
  background-color: var(--color-primary-dark);
  color: #ffffff;
}

table th,
table td {
  padding: var(--spacing-sm);
  text-align: left;
  border-bottom: 1px solid var(--color-border);
}

table tbody tr:hover {
  background-color: var(--color-neutral-light);
}

table tbody tr:nth-child(even) {
  background-color: #ffffff;
}

.badge {
  display: inline-block;
  padding: 0.25rem 0.75rem;
  font-size: 0.8rem;
  font-weight: 600;
  border-radius: 20px;
  background-color: var(--color-neutral-medium);
  color: var(--color-text);
}

.badge-primary {
  background-color: var(--color-primary);
  color: #ffffff;
}

.badge-accent {
  background-color: var(--color-accent-dark-bg);
  color: #fdfdfd;
}

.badge-success {
  background-color: var(--color-success);
  color: #ffffff;
}

.section {
  padding: var(--spacing-2xl) 0;
}

.section-title {
  text-align: center;
  margin-bottom: var(--spacing-2xl);
}

.hero {
  background: linear-gradient(135deg, var(--color-primary-dark) 0%, var(--color-primary) 100%);
  color: #ffffff;
  padding: var(--spacing-2xl) 0;
  text-align: center;
}

.hero h1 {
  color: #ffffff;
  margin-bottom: var(--spacing-md);
}

.hero p {
  font-size: 1.25rem;
  margin-bottom: var(--spacing-lg);
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

.hero-cta {
  display: flex;
  gap: var(--spacing-md);
  justify-content: center;
  flex-wrap: wrap;
}

.highlight-box {
  background-color: var(--color-neutral-light);
  padding: var(--spacing-lg);
  border-radius: var(--radius-lg);
  border-left: 4px solid var(--color-accent);
}

.highlight-box strong {
  color: var(--color-primary-dark);
}

@media (max-width: 600px) {
  html {
    font-size: 14px;
  }

  .site-header .container {
    flex-direction: column;
    gap: var(--spacing-md);
  }

  .site-header nav {
    gap: var(--spacing-md);
    justify-content: center;
    width: 100%;
  }

  .site-header nav a {
    font-size: 0.9rem;
  }

  h1 {
    font-size: 1.75rem;
  }

  h2 {
    font-size: 1.5rem;
  }

  h3 {
    font-size: 1.25rem;
  }

  .container {
    padding: 0 var(--spacing-sm);
  }

  .grid-2,
  .grid-3,
  .grid-4 {
    grid-template-columns: 1fr;
  }

  table {
    font-size: 0.85rem;
  }

  table th,
  table td {
    padding: 0.5rem 0.25rem;
  }

  .card {
    padding: var(--spacing-md);
  }

  .hero {
    padding: var(--spacing-xl) 0;
  }

  .hero p {
    font-size: 1rem;
  }

  .hero-cta {
    flex-direction: column;
  }

  .hero-cta .btn {
    width: 100%;
  }

  .section {
    padding: var(--spacing-xl) 0;
  }

  .section-title {
    margin-bottom: var(--spacing-xl);
  }
}

@media (min-width: 601px) {
  .site-header nav {
    gap: var(--spacing-xl);
  }

  .grid {
    gap: var(--spacing-xl);
  }

  table {
    font-size: 1rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  * {
    animation: none !important;
    transition: none !important;
  }
}

pages.css:
.speakers-intro {
